const conv = ($('get_data').first().json.conversation || '').toString().toLowerCase().trim();
const btnTexto = ($('get_data').first().json.btn_data || '').toString().toLowerCase().trim();
const raw = btnTexto || conv;

const opcoes = {
  '1': 'suporte', 'btn1': 'suporte', 'suporte': 'suporte',
  '2': 'financeiro', 'btn2': 'financeiro', 'financeiro': 'financeiro',
  'financeiro e com': 'financeiro', 'financeiro e com.': 'financeiro',
  '3': 'agrotech', 'btn3': 'agrotech', 'agrotech': 'agrotech'
};

const opcao = opcoes[raw] || 'erro';

return [{ json: { rota: opcao, departamento: opcao === 'erro' ? '' : opcao, input_recebido: raw } }];

const conv = ($('get_data').first().json.conversation || '').toString().toLowerCase().trim();
const btnTexto = ($('get_data').first().json.btn_data || '').toString().toLowerCase().trim();

// 🟢 O SEGREDO AQUI: Priorizar o TÍTULO do botão (btnTexto) em vez do ID genérico (btn2)
const raw = btnTexto || conv;

// 1. Mapeia a entrada do utilizador para uma chave padrão
let chave = '';

// Como priorizamos o texto, se o usuário clicar no menu antigo, 
// o 'raw' será "financeiro e com." e ele NÃO vai entrar na regra abaixo!
if (['1', 'btn1', 'fiscal'].includes(raw)) {
  chave = 'fiscal';
} 
else if (['2', 'btn2', 'financeiro'].includes(raw)) {
  chave = 'financeiro';
} 
else if (['3', 'btn3', 'operacional'].includes(raw)) {
  chave = 'operacional';
}

// 2. Define o departamento e a fila para cada chave
const config = {
  'fiscal': { departamento: 'suporte_fiscal', fila: 'N2-Suporte' },
  'financeiro': { departamento: 'suporte_financeiro', fila: 'Financeiro' },
  'operacional': { departamento: 'suporte_operacional', fila: 'N1-Suporte' }
};

// 3. Obtém o resultado ou retorna erro
const resultado = config[chave];

return [{
  json: {
    input_recebido: raw,
    rota: resultado ? 'sucesso' : 'erro',
    departamento: resultado ? resultado.departamento : '',
    fila: resultado ? resultado.fila : ''
  }
}];

// ==========================================
// ➔ MATRIZ ÚNICA DE CONFIGURAÇÃO (GERAL)
// ==========================================
// Os turnos estão em MINUTOS totais do dia
// ==========================================
// ➔ MATRIZ ÚNICA DE CONFIGURAÇÃO (GERAL)
// ==========================================

const EQUIPE = [
  { nome: 'gabriel',   id: 5,  deptos: ['suporte', 'suporte_operacional', 'financeiro'],  filas: [6, 2],    turnos: [[420, 650], [750, 1010]] }, // Saída 16:50
  { nome: 'pedro',     id: 6, deptos: ['suporte', 'suporte_fiscal'],                     filas: [7],       turnos: [[430, 650], [750, 1010]] }, // Saída 16:50
  { nome: 'gustavo',   id: 7,  deptos: ['suporte', 'suporte_fiscal'],                     filas: [7],       turnos: [[490, 740], [840, 1070]] }, // Saída 17:50
  { nome: 'kariny',    id: 4,  deptos: ['suporte', 'suporte_operacional', 'financeiro'],  filas: [6, 2, 1], turnos: [[490, 740], [840, 1070]] }, // Saída 17:50
  { nome: 'geneses',   id: 9,  deptos: ['suporte', 'suporte_fiscal'],                     filas: [7],       turnos: [[490, 740], [840, 1070]] }, // Saída 17:50
  { nome: 'thiago',    id: 11, deptos: ['suporte'],                                       filas: [8],       turnos: [[490, 740], [840, 1070]] }, // Saída 17:50
  { nome: 'junior',    id: 8,  deptos: ['suporte'],                                       filas: [8],       turnos: [[490, 740], [840, 1070]] }, // Saída 17:50 
  { nome: 'guilherme', id: 10, deptos: ['suporte', 'suporte_operacional'],                filas: [6],       turnos: [[490, 740], [840, 1070]] }, // Saída 17:50
  { nome: 'tainara',   id: 3,  deptos: ['suporte'],                                       filas: [1],       turnos: [[450, 690], [780, 1055]] }  // Saída 17:35
];

const FILA_FALLBACK_ID = 6;
const FILA_FALLBACK_NOME = 'N1-Suporte';

// ==========================================
// CÁLCULO DE HORÁRIO EXATO (America/Manaus)
// ==========================================
const agora = new Date();
const formatter = new Intl.DateTimeFormat("en-US", {
  timeZone: "America/Manaus", hour: "numeric", minute: "numeric", hour12: false
});

const parts = formatter.formatToParts(agora);
let horaAtual = parseInt(parts.find(p => p.type === 'hour').value, 10);
if (horaAtual === 24) horaAtual = 0; 
const minutoAtual = parseInt(parts.find(p => p.type === 'minute').value, 10);

const minutosAtuais = (horaAtual * 60) + minutoAtual;
const horaChatFormatada = `${String(horaAtual).padStart(2, '0')}:${String(minutoAtual).padStart(2, '0')}`;

// ==========================================
// IDENTIFICAÇÃO DO DEPARTAMENTO ALVO
// ==========================================
let deptoPuxado = '';
try { deptoPuxado = $('parse_menu_principal').first().json.departamento || ''; } catch (e) {}
if (!deptoPuxado) {
  try { deptoPuxado = $('parse_menu_suporte').first().json.departamento || ''; } catch (e) {}
}
const departamento = String(deptoPuxado || 'suporte').trim().toLowerCase();

const MAPA_FILAS = { suporte: 6, suporte_fiscal: 7, suporte_operacional: 6, financeiro: 2, suporte_financeiro: 2, agrotech: 4 };
const targetQueueId = MAPA_FILAS[departamento] || FILA_FALLBACK_ID;

// ==========================================
// PROCESSAMENTO DE CARGA DO BANCO
// ==========================================
const itensDoBanco = $input.all();
const cargaAtendimentos = {};
for (const item of itensDoBanco) {
  const logs = Array.isArray(item.json) ? item.json : [item.json];
  for (const log of logs) {
    if (log.id_user) {
      cargaAtendimentos[Number(log.id_user)] = (cargaAtendimentos[Number(log.id_user)] || 0) + Number(log.contagem_transferencia || 0);
    }
  }
}

const apiResp = $('buscar por usuarios online').first().json;
const usuariosRaw = apiResp.data || apiResp.body?.data || [];

// ==========================================
// FILTRAGEM DINÂMICA VIA ARRAY UNIFICADO
// ==========================================
const candidatosValidos = [];

for (const usuarioAPI of usuariosRaw) {
  const uid = Number(usuarioAPI.id);

  if (usuarioAPI.profile === 'admin' && uid !== 4) continue; 

  const statusOnline = usuarioAPI.isOnline;
  const taOnline = statusOnline === true || statusOnline === "true" || statusOnline === 1;
  if (!taOnline) continue;

  const config = EQUIPE.find(e => e.id === uid || String(usuarioAPI.name).toLowerCase().includes(e.nome));
  if (!config) continue;

  const pertenceAoDestino = config.deptos.includes(departamento) || config.filas.includes(Number(targetQueueId));
  if (!pertenceAoDestino) continue;

  const estaNoExpediente = config.turnos.some(([inicio, fim]) => minutosAtuais >= inicio && minutosAtuais <= fim);
  if (!estaNoExpediente) continue;

  candidatosValidos.push({
    userId: uid,
    name: usuarioAPI.name,
    qtdAtendimentos: cargaAtendimentos[uid] || 0,
    queueId: targetQueueId,
    queueName: usuarioAPI.queues?.find(q => Number(q.id) === Number(targetQueueId))?.queue || FILA_FALLBACK_NOME
  });
}

// ==========================================
// DECISÃO DE ENVIO: PRIORIDADE TOTAL PARA A MENOR CARGA
// ==========================================
let chosen = null;
let status = 'open';
let modoDistribuicao = 'fila_menor_carga';

function selecionarAnalistaComMenorCarga(lista) {
  lista.sort((a, b) => a.qtdAtendimentos - b.qtdAtendimentos);
  const menorCargaEncontrada = lista[0].qtdAtendimentos;
  const empatados = lista.filter(c => c.qtdAtendimentos === menorCargaEncontrada);

  if (empatados.length > 1) {
    modoDistribuicao = 'fila_empate_aleatorio';
    const indexAleatorio = Math.floor(Math.random() * empatados.length);
    return empatados[indexAleatorio];
  } else {
    modoDistribuicao = 'fila_menor_carga';
    return lista[0];
  }
}

if (candidatosValidos.length > 0) {
  chosen = selecionarAnalistaComMenorCarga(candidatosValidos);
} else {
  // 🟢 SE NINGUÉM DO DEPTO ESTIVER DISPONÍVEL NO HORÁRIO: Joga como PENDING para a triagem da fila
  status = 'pending';
  modoDistribuicao = 'fallback_no_online';

  const candidatosFallback = [];
  for (const usuarioAPI of usuariosRaw) {
    const uid = Number(usuarioAPI.id);
    const statusOnline = usuarioAPI.isOnline;
    const taOnline = statusOnline === true || statusOnline === "true" || statusOnline === 1;
    if (!taOnline) continue;

    const config = EQUIPE.find(e => e.id === uid || String(usuarioAPI.name).toLowerCase().includes(e.nome));
    if (config && config.turnos.some(([inicio, fim]) => minutosAtuais >= inicio && minutosAtuais <= fim)) {

      const filaIdDinamica = config.filas[0] || FILA_FALLBACK_ID;
      const filaNomeDinamica = usuarioAPI.queues?.find(q => Number(q.id) === Number(filaIdDinamica))?.queue || FILA_FALLBACK_NOME;

      candidatosFallback.push({
        userId: uid,
        name: usuarioAPI.name,
        qtdAtendimentos: cargaAtendimentos[uid] || 0,
        queueId: filaIdDinamica,
        queueName: filaNomeDinamica
      });
    }
  }

  if (candidatosFallback.length > 0) {
    chosen = selecionarAnalistaComMenorCarga(candidatosFallback);
    status = 'open';
    modoDistribuicao = 'redirected_' + modoDistribuicao;
  }
}

return [{
  json: {
    departamento,
    queueId: chosen ? Number(chosen.queueId) : Number(targetQueueId),
    queueName: chosen ? chosen.queueName : FILA_FALLBACK_NOME,
    userId: chosen ? chosen.userId : null,
    status, 
    horaChat: horaChatFormatada,
    minutosAtualServidor: minutosAtuais,
    atendenteNome: chosen ? chosen.name : null,
    atendenteOnline: chosen ? true : false,
    modoDistribuicao,
    ticketId: $('get_data').first().json.ticketID,
    clienteID: $('get_data').first().json.clienteID
  }
}];

