  }
}

const apiResp = $('buscar por usuarios online1').first().json;
const usuariosRaw = apiResp.data || apiResp.body?.data || [];

// ==========================================
// FILTRAGEM DINÂMICA VIA ARRAY UNIFICADO
// ==========================================
const candidatosValidos = [];

for (const usuarioAPI of usuariosRaw) {
  if (usuarioAPI.profile === 'admin' && usuarioAPI.id !== 4) continue; // Kariny liberada
  if (usuarioAPI.isOnline !== true) continue; // Só avalia quem está efetivamente com Z-Pro logado

  const config = EQUIPE.find(e => e.id === usuarioAPI.id || usuarioAPI.name.toLowerCase().includes(e.nome));
  if (!config) continue;

  // 1. Valida se o analista pertence à rota do departamento/fila solicitado
  const pertenceAoSuporte = config.deptos.includes(departamento) || config.filas.includes(targetQueueId);
  if (!pertenceAoSuporte) continue;

  // 2. Valida de forma EXATA se o analista está no seu turno no fuso de Manaus
  const estaNoExpediente = config.turnos.some(([inicio, fim]) => minutosAtuais >= inicio && minutosAtuais <= fim);
  if (!estaNoExpediente) continue;

  candidatosValidos.push({
    userId: usuarioAPI.id,
    name: usuarioAPI.name,
    qtdAtendimentos: cargaAtendimentos[usuarioAPI.id] || 0, // Carga injetada aqui
    queueId: targetQueueId,
    queueName: usuarioAPI.queues?.find(q => q.id === targetQueueId)?.queue || FILA_FALLBACK_NOME
  });
}

// ==========================================
// DECISÃO DE ENVIO: PRIORIDADE TOTAL PARA A MENOR CARGA
// ==========================================
let chosen = null;
let status = 'open';
let modoDistribuicao = 'fila_menor_carga';

// 🟢 FUNÇÃO DE DESEMPATE SEGURO
function selecionarAnalistaComMenorCarga(lista) {
  // 1. Ordena rigorosamente (do menor para o maior atendimento)
  lista.sort((a, b) => a.qtdAtendimentos - b.qtdAtendimentos);

  // 2. Isola o número da menor carga e filtra quem tem exatamente esse número
  const menorCargaEncontrada = lista[0].qtdAtendimentos;
  const empatados = lista.filter(c => c.qtdAtendimentos === menorCargaEncontrada);

  // 3. Se houver empate entre os menores, sorteia; se não, vence quem tem menos
  if (empatados.length > 1) {
    modoDistribuicao = 'fila_empate_aleatorio';
    const indexAleatorio = Math.floor(Math.random() * empatados.length);
    return empatados[indexAleatorio];
  } else {
    modoDistribuicao = 'fila_menor_carga';
    return lista[0];
  }
}

if (candidatosValidos.length > 0) {
  chosen = selecionarAnalistaComMenorCarga(candidatosValidos);
} else {
  // 🟢 SE NINGUÉM DO SUPORTE ESTIVER DISPONÍVEL NO HORÁRIO: Joga como PENDING
  status = 'pending';
  modoDistribuicao = 'fallback_no_online';

  const candidatosFallback = [];
  for (const usuarioAPI of usuariosRaw) {
    if (usuarioAPI.isOnline !== true) continue;

    const config = EQUIPE.find(e => e.id === usuarioAPI.id || usuarioAPI.name.toLowerCase().includes(e.nome));
    if (config && config.turnos.some(([inicio, fim]) => minutosAtuais >= inicio && minutosAtuais <= fim)) {

      const filaIdDinamica = config.filas[0] || FILA_FALLBACK_ID;
      const filaNomeDinamica = usuarioAPI.queues?.find(q => q.id === filaIdDinamica)?.queue || FILA_FALLBACK_NOME;

      candidatosFallback.push({
        userId: usuarioAPI.id,
        name: usuarioAPI.name,
        qtdAtendimentos: cargaAtendimentos[usuarioAPI.id] || 0,
        queueId: filaIdDinamica,
        queueName: filaNomeDinamica
      });
    }
  }

  // Se achar alguém válido no fallback, aplica a mesma regra da MENOR carga
  if (candidatosFallback.length > 0) {
    chosen = selecionarAnalistaComMenorCarga(candidatosFallback);
    status = 'open';
    modoDistribuicao = 'redirected_' + modoDistribuicao;
  }
}

return [{
  json: {
    departamento,
    queueId: chosen ? Number(chosen.queueId) : Number(targetQueueId),
    queueName: chosen ? chosen.queueName : FILA_FALLBACK_NOME,
    userId: chosen ? chosen.userId : null,
    status, 
    horaChat: horaChatFormatada,
    minutosAtualServidor: minutosAtuais, // Para você conseguir debugar e ver se o cálculo bate
    atendenteNome: chosen ? chosen.name : null,
    atendenteOnline: chosen ? true : false,
    modoDistribuicao,
    ticketId: $('get_data').first().json.ticketID,
    clienteID: $('get_data').first().json.clienteID
  }
}];

